 const sg=`<table class="sg"><tr>${T.sg.map((l,i)=>{const s=f.sg[i]||{};return`<td style="width:${Math.floor(100/T.sg.length)}%">${E(l)} ........................................<br>( ${E(s.n)||'&nbsp;'.repeat(30)} )<br>${SP(s.p)}<br>วันที่ .............................</td>`}).join('')}</tr></table>`;
